public class InvocationMatcher_captureArgumentsFrom_TriageGen1Test {

    // Mocking the CapturesArguments interface/class as it is used for casting
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object arg);
    }

    private Method createVarargsMethod() throws NoSuchMethodException {
        return String.class.getMethod("format", String.class, Object[].class);
    }

    private Method createNonVarargsMethod() throws NoSuchMethodException {
        return String.class.getMethod("length");
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_AllCapturers() throws NoSuchMethodException {
        Method method = createNonVarargsMethod();
        Invocation invocation = mock(Invocation.class);
        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        Matcher regularMatcher = mock(Matcher.class);

        when(invocation.getMethod()).thenReturn(method);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"arg1", "arg2"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg1");
        when(invocation.getArgumentAt(1, Object.class)).thenReturn("arg2");

        List<Matcher> matchers = Arrays.asList(capturer1, regularMatcher, capturer2);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        verify(capturer1).captureFrom("arg1");
        verify(capturer2).captureFrom("arg2");
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_NoCapturers() throws NoSuchMethodException {
        Method method = createNonVarargsMethod();
        Invocation invocation = mock(Invocation.class);
        Matcher matcher1 = mock(Matcher.class);

        when(invocation.getMethod()).thenReturn(method);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"arg1"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg1");

        List<Matcher> matchers = Arrays.asList(matcher1);
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        invocationMatcher.captureArgumentsFrom(invocation);
        // No exception means successful pass through
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_MixedMatchers() throws NoSuchMethodException {
        // String.format(String format, Object... args)
        Method method = String.class.getMethod("format", String.class, Object[].class);
        Invocation invocation = mock(Invocation.class);

        CapturesArguments nonVarargCapturer = mock(CapturesArguments.class);
        CapturesArguments varargCapturer = mock(CapturesArguments.class);
        Matcher regularMatcher = mock(Matcher.class);

        // Arguments: [formatString, arg1, arg2]
        // In varargs, the last index is the varargs array. 
        // indexOfVararg = 3 - 1 = 2.
        Object[] rawArgs = new Object[]{"%s %s", "val1", "val2"};

        when(invocation.getMethod()).thenReturn(method);
        when(invocation.getRawArguments()).thenReturn(rawArgs);
        // getArgumentAt handles non-vararg parts
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("%s %s");

        // The code logic:
        // indexOfVararg = 2.
        // Loop 1: position 0 to 1.
        // Loop 2: position 2 to matchers.size().

        List<Matcher> matchers = Arrays.asList(nonVarargCapturer, regularMatcher, varargCapturer);
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        invocationMatcher.captureArgumentsFrom(invocation);

        // nonVarargCapturer is at pos 0. 0 < 2.
        verify(nonVarargCapturer).captureFrom("%s %s");

        // varargCapturer is at pos 2. 2 >= 2.
        // it uses invocation.getRawArguments()[2 - 2] => rawArgs[0]
        // Wait, looking at the code: position - indexOfVararg. 
        // If position is 2 and indexOfVararg is 2, it accesses rawArgs[0].
        // This logic seems to imply that the vararg capture assumes the matchers list 
        // is aligned with the varargs array elements starting from index 0.
        verify(varargCapturer).captureFrom("val1"); 
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_OnlyVarargCapturers() throws NoSuchMethodException {
        Method method = String.class.getMethod("format", String.class, Object[].class);
        Invocation invocation = mock(Invocation.class);
        CapturesArguments varargCapturer = mock(CapturesArguments.class);

        Object[] rawArgs = new Object[]{"%s", "val1"}; // length 2, indexOfVararg = 1
        when(invocation.getMethod()).thenReturn(method);
        when(invocation.getRawArguments()).thenReturn(rawArgs);

        // Matchers: [capturer] -> position 0. 
        // Since indexOfVararg is 1, pos 0 is handled by the first loop.
        List<Matcher> matchers = Arrays.asList(varargCapturer);
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        when(invocation.getArgumentAt(0, Object.class)).thenReturn("%s");

        invocationMatcher.captureArgumentsFrom(invocation);
        verify(varargCapturer).captureFrom("%s");
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_ComplexLoop() throws NoSuchMethodException {
        Method method = String.class.getMethod("format", String.class, Object[].class);
        Invocation invocation = mock(Invocation.class);

        CapturesArguments capturer0 = mock(CapturesArguments.class); // non-vararg
        CapturesArguments capturer1 = mock(CapturesArguments.class); // vararg part 1
        CapturesArguments capturer2 = mock(CapturesArguments.class); // vararg part 2

        Object[] rawArgs = new Object[]{"%s %s %s", "a", "b", "c"}; // length 4, indexOfVararg = 3
        when(invocation.getMethod()).thenReturn(method);
        when(invocation.getRawArguments()).thenReturn(rawArgs);
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("%s %s %s");

        // Matchers: [0: capturer0, 1: capturer1, 2: capturer2, 3: capturer3]
        // indexOfVararg = 3.
        // Loop 1 (0 to 2):
        // pos 0: capturer0 -> getArgumentAt(0)
        // pos 1: capturer1 -> getArgumentAt(1)
        // pos 2: capturer2 -> getArgumentAt(2)
        // Loop 2 (3 to 3):
        // pos 3: capturer3 -> getRawArguments()[3-3] = rawArgs[0]

        List<Matcher> matchers = new ArrayList<>();
        matchers.add(capturer0);
        matchers.add(capturer1);
        matchers.add(capturer2);
        matchers.add(capturer1); // reuse to verify logic

        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        when(invocation.getArgumentAt(1, Object.class)).thenReturn("arg1");
        when(invocation.getArgumentAt(2, Object.class)).thenReturn("arg2");

        invocationMatcher.captureArgumentsFrom(invocation);

        verify(capturer0).captureFrom("%s %s %s");
        verify(capturer1).captureFrom("arg1");
        verify(capturer2).captureFrom("arg2");
        // The 4th matcher (pos 3) is capturer1. It calls rawArgs[3-3] = rawArgs[0]
        verify(capturer1).captureFrom("%s %s %s");
    }
}
